const OBSERVER = "https://learn.microsoft.com/en-us/dotnet/standard/events/observer-design-pattern";

function buildQuestion(old, spec, unit, index) {
  const questionId = spec.retarget
    ? old.questionId.replace(/i(\d+)$/, (_, n) => `i${String(Number(n) + 18).padStart(3, "0")}`)
    : old.questionId;
  const suffix = `${unit.slice(-3).toLowerCase()}_${questionId.slice(-4)}`;
  const correctId = `n06_${suffix}_policy`;
  const options = [
    { optionId: correctId, text: spec.key },
    ...spec.wrong.map((wrong, wrongIndex) => ({ optionId: `n06_${suffix}_alt${wrongIndex + 1}`, text: wrong.option })),
  ];
  const messages = spec.wrong.map((wrong, wrongIndex) => ({
    kind: "wrong_option",
    targetId: `n06_${suffix}_alt${wrongIndex + 1}`,
    text: wrong.feedback,
  }));
  return {
    questionId,
    trackId: TRACK,
    nodeId: NODE,
    mentalUnitId: unit,
    prompt: spec.prompt,
    difficulty: old.difficulty,
    interaction: { type: "choice_single", scoringMethod: "exact_selected_set", options },
    answer: { type: "choice_single", optionId: correctId },
    feedback: {
      type: "choice_single",
      reason: spec.reason,
      details: {
        mechanismOrProperty: spec.mechanism,
        scenarioApplication: spec.application,
        errorCorrection: spec.error,
        boundaryOrTradeoff: spec.boundary,
        transfer: spec.transfer,
      },
      messages,
    },
    sourceRefs: unit === "OOD-N06-B04" ? [OBSERVER, BOOK] : [BOOK],
  };
}

function writeUnit(unit, objective, rows) {
  const relative = `content/object-oriented-design-interview/${NODE}/${unit}.json`;
  const sourceBytes = readFileSync(path.join(ROOT, relative));
  assert.equal(createHash("sha256").update(sourceBytes).digest("hex"), SOURCES[unit], `${unit} current source baseline`);
  const before = JSON.parse(sourceBytes.toString("utf8"));
  assert.equal(before.length, rows.length, `${unit} row count`);
  const questions = rows.map((row, index) => buildQuestion(before[index], row, unit, index));
  writeFileSync(path.join(PACKET, `proposals/${unit.slice(4)}.json`), `${JSON.stringify(questions, null, 2)}\n`);
  return questions.map((question, index) => ({
    beforeQuestionId: before[index].questionId,
    questionId: question.questionId,
    mentalUnitId: unit,
    learningObjective: rows[index].learningObjective ?? `Choose a design that enforces ${rows[index].decisiveFact.charAt(0).toLowerCase()}${rows[index].decisiveFact.slice(1)}`,
    decisiveFact: rows[index].decisiveFact,
    nearestAlternative: rows[index].nearestAlternative,
    changedCondition: rows[index].changedCondition,
    identityAction: question.questionId === before[index].questionId ? "preserve_question_id" : "replace_question_with_new_id",
    identityReason: question.questionId === before[index].questionId
      ? rows[index].identityReason
      : `The before accepted key was: “${before[index].interaction.options.find((option) => option.optionId === before[index].answer.optionId)?.text}” The new case asks the learner to decide: “${rows[index].decisiveFact}” This changes the supported case-specific decision, so the manifest's reserved replacement ID is used.`,
    sourceRefs: question.sourceRefs,
  }));
}

